  "/ccr009-reporting-checklist-motor-dealers": {
    "title": "CCR009 Reporting Checklist for Motor Dealers",
    "answer": "Use this CCR009 checklist when the draft return and supporting records are ready for final review. Check the firm, period, applicable questions, reconciliations, unresolved items and submitter access; then confirm the return was actually submitted. It is a practical readiness aid, not the FCA form or a replacement for your firm’s deadline.",
    "sections": [
      {
        "title": "Final readiness checklist",
        "paragraphs": [
          "Copy these tasks into your own working record and add an owner, target date and status. The suggested evidence helps demonstrate how an answer was prepared; it is not a list of additional documents the FCA always requires you to upload."
        ],
        "bullets": [],
        "columns": [
          "Task",
          "Suggested completion evidence"
        ],
        "rows": [
          [
            "Correct firm and return",
            "Firm Reference Number (FRN), return name, reporting period and deadline match the schedule."
          ],
          [
            "Applicable questions answered",
            "Answers follow the current form, notes and relevant question route."
          ],
          [
            "Evidence and figures checked",
            "Source records, definitions, period boundaries and calculations agree."
          ],
          [
            "Open items resolved",
            "Missing data, unsupported zeros, duplicates and material discrepancies investigated."
          ],
          [
            "Review completed",
            "The responsible person has checked the final version; record unresolved escalation if any."
          ],
          [
            "Submitter ready",
            "The intended user has access to submit this return; absence cover has been considered."
          ],
          [
            "Submission confirmed",
            "After submitting, check the final status and retain the confirmation. A saved draft is not completion."
          ]
        ],
        "sources": [
          {
            "id": "ccr",
            "label": "FCA: CCR009 reporting, scope and submission",
            "href": "https://www.fca.org.uk/firms/consumer-credit-reporting/ccr009"
