config/offer.js.text:
/*
 * FCA Authorisation Assistance — commercial terms shown on the website.
 *
 * Single source for every price, term and qualification that appears on the
 * homepage, /fca-authorisation-motor-dealers, /pricing, /referral, the FAQs
 * and the structured data. Change a value here and every page follows.
 *
 * Anything left as null is UNCONFIRMED: templates hide it (or show a neutral
 * "being confirmed" note) and the server prints a reminder at start-up.
 */
const offer = {
  name: 'FCA Authorisation Assistance',
  audience: 'Car, motorcycle, van and commercial vehicle dealers applying for FCA authorisation',

  // ---- Confirmed by the business owner (October 2026) ----
  startPayment: 100,          // £100 to get started …
  startIsFirstMonth: true,    // … which IS the first monthly payment (not an extra setup fee)
  monthlyPayment: 100,        // £100 per month thereafter
  paymentMethod: 'Direct Debit',
  minimumTermMonths: 6,       // six-month minimum commitment
  fcaFeeSeparate: true,       // the FCA application fee is paid separately
  continuesUntilCancelled: true,
  reportingMonthly: 100,      // continuing reporting support base fee; active referral discounts apply

  // Genuine former price, shown only as clearly labelled historical context.
  previousPrice: {
    amount: 1000,
    label: 'Previous one-off application assistance fee'
  },

  minimumTotal: {
    amount: 600,
    explanation: 'Your £100 first payment is the first of the six monthly payments, so the minimum service commitment is £600, before any applicable referral adjustments.'
  },
  afterMinimumTerm: 'After six months, payments continue monthly until you cancel under the agreed cancellation terms.',
  decisionTimingTerms: 'If authorisation is approved before six months, the service continues with reporting and compliance support within the agreed scope.',

  // ---- UNCONFIRMED — leave null until confirmed ----
  // e.g. 'Prices include VAT.' / 'Prices exclude VAT, charged at the standard rate.' / 'VAT is not charged.'
  vatStatement: null,
  // Short label for the comparison table once confirmed, e.g. 'Inc. VAT' / '+ VAT' / 'No VAT'.
  vatShort: null,
  // Cancellation notice period — do NOT invent. e.g. 'Cancel with 30 days’ written notice.'
  cancellationNotice: null
};

const words = { 3: 'three', 6: 'six', 12: 'twelve' };
offer.minimumTermWords = words[offer.minimumTermMonths] || String(offer.minimumTermMonths);
offer.minimumTermTitle = offer.minimumTermWords.charAt(0).toUpperCase() + offer.minimumTermWords.slice(1);
offer.summary = `£${offer.startPayment} to get started, then £${offer.monthlyPayment} per month by ${offer.paymentMethod}, with a ${offer.minimumTermWords}-month minimum term.`;
// The qualification line that must sit directly beneath the offer.
offer.qualifier = `First month included. ${offer.minimumTermTitle}-month minimum term: £${offer.minimumTotal.amount} minimum service commitment. Payments continue monthly until cancellation. FCA application fee payable separately.`;

offer.unconfirmed = Object.entries({
  'VAT treatment of the £100 payments (config/offer.js → vatStatement, vatShort)': offer.vatStatement,
  'Cancellation notice period after the minimum term (config/offer.js → cancellationNotice)': offer.cancellationNotice
}).filter(([, value]) => value === null || value === undefined || value === '').map(([label]) => label);

module.exports = offer;

config/campaign.js.text:
/*
 * Christmas campaign — one configurable deadline.
 *
 * The campaign runs until the END of 25 December 2026, Europe/London time.
 * In December the UK is on GMT (UTC+0), so the end of 25 December is
 * 2026-12-26T00:00:00Z. Change DEADLINE_ISO here and every page, the
 * countdown and the "closes" labels follow.
 *
 * After the deadline every festive element and campaign label is removed
 * automatically (server-side, on every request — no JavaScript needed).
 * This file never touches billing: existing customers are unaffected.
 */
const DEADLINE_ISO = '2026-12-26T00:00:00Z';   // end of Fri 25 Dec 2026, Europe/London
const CLOSING_LABEL = '25 December 2026';        // shown to visitors (also without JavaScript)
const CLOSING_DATE_ISO = '2026-12-25';          // machine-readable closing date for <time>

/*
 * What visitors see after the campaign ends. Same pricing confirmed 29 October 2026.
 *   mode: 'unconfirmed' → authorisation price blocks are replaced with a neutral
 *                          "speak to us about current pricing" panel. No price is invented.
 *   mode: 'continue'    → keep showing the £100/month offer from config/offer.js,
 *                          without any Christmas branding or closing date.
 *   mode: 'custom'      → show `headline` and `text` below in place of the price.
 */
const postCampaign = {
  mode: 'continue',
  headline: null,
  text: null
};

const deadline = new Date(DEADLINE_ISO);

function state(now = new Date()) {
  // Optional override for testing only, e.g. CAMPAIGN_NOW=2026-12-26T00:00:01Z
  const override = process.env.CAMPAIGN_NOW ? new Date(process.env.CAMPAIGN_NOW) : null;
  const at = override && !Number.isNaN(override.getTime()) ? override : now;
  const active = at.getTime() < deadline.getTime();
  const showPrice = active || postCampaign.mode === 'continue';
  return {
    active,
    expired: !active,
    deadlineIso: DEADLINE_ISO,
    closingLabel: CLOSING_LABEL,
    closingDateIso: CLOSING_DATE_ISO,
    daysLeft: active ? Math.ceil((deadline.getTime() - at.getTime()) / 86400000) : 0,
    showPrice,
    post: postCampaign
  };
}

module.exports = { DEADLINE_ISO, CLOSING_LABEL, postCampaign, state };

config/referral.js.text:
/* Each active qualifying referral discounts the ongoing core subscription by
 * 25 percentage points, including reporting after authorisation. This is the
 * public scheme configuration, not a connected billing or referral ledger.
 */
const STEP = 25;
const MAX_REFERRALS = 4;
const tiers = Array.from({ length: MAX_REFERRALS + 1 }, (_, n) => ({ referrals: n, percent: Math.min(n * STEP, 100) }));
const eligibilityTerms = '<p>A referral qualifies once the dealer completes onboarding, we identify the introducer, accept the dealer as a new customer and receive their first subscription payment. They must remain subscribed and up to date with payments. Each active qualifying referral reduces your subsequent core monthly subscription by 25%, capped at 100%, including continuing reporting support after FCA authorisation. The initial £100 payment remains payable. FCA fees, other third-party charges and separately purchased services or subscriptions are excluded.</p><p>If a referred customer cancels or stops qualifying, that referral’s 25% discount ends from your next invoice. The discounts for your other active qualifying referrals remain. On a £100 monthly subscription, one referral leaving changes £75 to £100; one of two leaving changes £50 to £75. Authorisation itself does not end the discount. See <a href="/terms">section 8 of the Terms of Business</a> for all eligibility restrictions and scheme-change terms.</p>';
const unresolved = [];
module.exports = { STEP, MAX_REFERRALS, tiers, eligibilityTerms, unresolved };

