ellipse(0,-9,31,16,grad(-25,-25,25,5,'#c99665','#8c5839'));path('M-27 -8 Q-45 -18 -43 -44 L-29 -43 Q-29 -28 -13 -18 Z','#b98256');ellipse(-39,-42,17,10,'#bf8c61');ellipse(-50,-39,9,7,'#d4ac7f');ellipse(-57,-40,3,3,'#392c2a');ellipse(-38,-46,2,2,'#1d2330');path('M-33 -50 Q-26 -66 -20 -57 Q-24 -47 -33 -50','#a36d47');path('M-37 -51 L-42 -68 L-39 -78 M-42 -68 L-51 -73 L-53 -81 M-42 -65 L-31 -71 L-30 -79',null,'#735440',3);path('M-28 -29 L-36 -23 M-13 -22 L-7 6',null,'#b8263c',5);ellipse(-31,-25,3,3,'#f3ca69');path('M27 -14 Q44 -25 36 -10 Z','#e6c299');ctx.restore()}
function sleighBack(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ellipse(25,-29,23,26,'#856445');path('M9 -44 Q20 -58 35 -46 L36 -31 L8 -31 Z','#a38252');path('M-42 -37 L-36 7 L40 7 L45 -32 Q32 -46 22 -29 L-20 -24 Z','#86152d');ctx.restore()}
function sleighFront(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);path('M-50 -17 Q-42 15 -22 18 L24 18 Q49 17 52 -8 L38 -6 Q36 5 24 4 L-21 4 Q-37 3 -38 -21 Z',grad(0,-20,0,20,'#d63b49','#99122c'),'#edc879',2);path('M-47 22 Q-42 31 -25 31 L36 31 Q55 30 58 18 M-25 17 L-23 30 M27 17 L28 30',null,'#e6c16f',3);path('M-27 10 Q0 23 28 10',null,'#efb866',1);ctx.restore()}
// Present sack sits over Santa's shoulder and follows his body movement.
function presentSack(x,y,s,t=0){
 ctx.save();ctx.translate(x-23*s,y-49*s);ctx.scale(s,s);ctx.rotate(Math.sin(t*4.49)*.035);
 ellipse(-7,12,21,27,grad(-24,-10,13,36,'#b68c43','#715125'));
 path('M-18 -8 L-22 -21 L-8 -17 L1 -22 L5 -7 Z','#c5a05a');
 path('M-18 -7 Q-7 -2 5 -7',null,'#f3cf7a',3);
 path('M-8 -5 Q-1 0 2 8 M-7 -5 Q-14 2 -12 8',null,'#e8bd62',2);
 // Visible wrapped presents and gold ribbons at the open top.
 ctx.fillStyle='#a91e36';ctx.fillRect(-17,-22,13,13);ctx.fillStyle='#f3cd72';ctx.fillRect(-12,-22,3,13);
 ctx.save();ctx.translate(-1,-18);ctx.rotate(.2);ctx.fillStyle='#2d796c';ctx.fillRect(-5,-9,12,15);ctx.fillStyle='#f4d68b';ctx.fillRect(0,-9,2,15);ctx.restore();
 path('M5 -7 Q25 -18 31 -1',null,'#d3ac60',3);ctx.restore();
}
// Artwork faces left natively. Reflect the entire team so reindeer lead to the right.
function teamBack(x,y,s,t,alpha,facing=-1){ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.scale(facing*s,s);
 deer(-177,-14,.76,t,0);deer(-96,-3,.76,t,1.9);
 path('M-156 -31 Q-70 15 -27 -21',null,'#b89251',1.5);
 path('M-88 -22 Q-54 -5 -27 -21',null,'#e2be73',1);
 sleighBack(0,0,1);ctx.restore();}
function teamFront(x,y,s,alpha,facing=-1){ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.scale(facing*s,s);sleighFront(0,0,1);ctx.restore();}
function draw(t){
 const s=scale,landX=cx,landY=cy;
 // Park the entire team to Santa's left, with room for his sack and arms.
 const fleetBase=Math.min(s,Math.max(.4,(landX-58)/285));
 const parkX=landX-285*fleetBase,parkY=landY-31*fleetBase;
 if(reduced){presentSack(landX,landY,s);santa(landX,landY,s,'stand',0);return;}
 const arrival=clamp((t-.4)/3.4),travel=arrival*arrival*(3-2*arrival);
 const climb=ease(clamp((arrival-.3)/.7));
 // Enter at mid-screen height, remain visible, then climb towards the berth.
 let sx=mix(-260*fleetBase,parkX,travel),sy=mix(H*.58,parkY,climb);
 let fleetScale=fleetBase,alpha=1,facing=t<3.8?-1:-Math.cos(clamp((t-3.8)/.65)*Math.PI);
 // A deliberate stationary parking beat while Santa stands and steps off.
 const departing=t>=7.6,departure=clamp((t-7.6)/3.4);
 if(departing){
  // Already turned in the berth: fly out LEFT without crossing Santa.
  facing=1;
  const distance=departure*departure*(3-2*departure);
  sx=mix(parkX,-300*fleetBase,distance);
  sy=parkY+Math.sin(departure*Math.PI)*22*fleetBase;
 }
 const fleetVisible=t<11;
 const stride=t<3.8?t:departing?3.8+(t-7.6):3.8;
 if(fleetVisible){
  for(let i=0;i<12;i++){const z=(t*.55+i*.083)%1;if(t<3.8||departing)star(sx-55*fleetScale-z*115*fleetScale,sy+Math.sin(i*3+t)*8,(1-z)*2.8,alpha*(1-z)*.6);}
  teamBack(sx,sy,fleetScale,stride,alpha,facing);
 }
 if(t<5.1){
  const rise=ease((t-4.15)/.75),footY=sy+13*fleetBase;
  if(t>4.15)presentSack(sx+5*fleetBase,footY,fleetBase*.87);
  santa(sx+5*fleetBase,footY,fleetBase*.87,rise>.8?'stand':'sit',t);
  if(fleetVisible)teamFront(sx,sy,fleetScale,alpha,facing);
 }else{
  // The empty sleigh stays parked while Santa steps over its side with his sack.
  if(fleetVisible)teamFront(sx,sy,fleetScale,alpha,facing);
  if(t<6.8){
   const step=clamp((t-5.1)/1.7),u=step*step*(3-2*step);
   const x=mix(parkX+5*fleetBase,landX,u),y=mix(parkY+13*fleetBase,landY,u)-Math.sin(u*Math.PI)*17*s;
   const size=mix(fleetBase*.87,s,u);
   presentSack(x,y,size,step);santa(x,y,size,'walk',step*2.8);
  }else{
   const dt=t-6.8;ellipse(landX,landY,23*s,2.3*s,'#00000030');
   const pose=guide&&t>=12?'stand':dt<.45?'land':dt<1.2?'wave':'dance',danceTime=dt<1.2?dt:dt-1.2;
   presentSack(landX,landY,s,pose==='dance'?danceTime:0);santa(landX,landY,s,pose,danceTime);
   if(dt<.6)for(let i=0;i<7;i++){const a=i/7*Math.PI;star(landX+Math.cos(a)*dt*48,landY-Math.sin(a)*dt*30,2.5*(1-dt/.6),1-dt/.6);}
  }
 }
}

 function render(){resize();ctx.clearRect(0,0,W,H);if(guide){canvas.hidden=reduced;fallback.hidden=!reduced;}if(!visible||document.hidden||!root.isConnected)return;
  // The arrival must remain visible below the card edge while climbing.
  ctx.save();draw(time);ctx.restore();
 }
 function tick(now){raf=0;if(!visible||document.hidden||reduced){last=0;render();return;}
  if(!root.isConnected)return;
  if(last)time+=Math.min((now-last)/1000,.05);last=now;render();if(guide&&time>=12){root.dataset.arrivalComplete='true';return;}raf=requestAnimationFrame(tick);
 }
 function wake(){cancelAnimationFrame(raf);raf=0;last=0;render();if(visible&&!document.hidden&&!reduced&&!(guide&&time>=12))raf=requestAnimationFrame(tick);}
 function check(){const b=card.getBoundingClientRect();const next=b.top<innerHeight && b.bottom>0;
  if(next!==visible){visible=next;wake();}else if(reduced)render();}
 window.addEventListener('scroll',check,{passive:true});window.addEventListener('resize',()=>{resize();check();if(reduced)render();},{passive:true});
 document.addEventListener('visibilitychange',wake);
 motion.addEventListener('change',e=>{reduced=e.matches;wake();});
 if('ResizeObserver' in window)new ResizeObserver(()=>{resize();check();}).observe(card);
 window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);raf=0;last=0;});
 window.addEventListener('pageshow',wake);
 resize();check();
});
})();

public/js/home-offer.js.text:
(() => {
 const init = () => document.querySelectorAll('[data-home-offer]').forEach(card => {
  if(card.dataset.homeOfferReady) return;
  card.dataset.homeOfferReady='true';
  const guide=card.hasAttribute('data-guide-gift');
  if(guide)card.closest('.guide-home-offer').classList.add('gift-motion-ready');
  const panel = card.querySelector('.offer-shell');
  const fallback = document.querySelector('[data-home-offer-fallback]');
  const deadline = Date.parse(card.dataset.deadline);
  const festive = !!card.closest('.has-festive-offer');
  if (festive) {
    const palette = {'#82b9ff':'#efbc72','#5093f7':'#d84958','#2563eb':'#a51d37','#e5f1fc':'#ffe6b0','#d0e9ff':'#f5d395','#d6edff':'#ffe6b0'};
    card.querySelectorAll('.present [fill], .present [stroke]').forEach(el => {
      for (const attr of ['fill', 'stroke']) {
        const value = el.getAttribute(attr);
        if (palette[value]) el.setAttribute(attr, palette[value]);
      }
    });
    [['box',['#eb6570','#ab1e3a']],['side',['#af1e39','#70172a']]].forEach(([id,colors]) => {
      card.querySelectorAll('#'+(card.dataset.svgPrefix||'')+id+' stop').forEach((stop,i) => stop.setAttribute('stop-color', colors[i]));
    });
  }
  let visible = !('IntersectionObserver' in window);
  const sync = () => panel.classList.toggle('paused', !visible || document.hidden);
  sync();
  document.addEventListener('visibilitychange', sync);
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(entries => { visible = entries[0].isIntersecting; sync(); }).observe(card);
  }
  const expire = () => {
    if (festive && Number.isFinite(deadline) && Date.now() >= deadline) {
      card.hidden = true;
      if (fallback) fallback.hidden = false;
      visible = false; sync();
    }
  };
  if(!guide){expire();setInterval(expire,1000);}
 });
 init();document.addEventListener('guideoffersupdated',init);
})();

public/css/guide-original-offers.css.text:
/* Original homepage/service designs, with guide-only spacing and finite motion. */
.researched-guide .guide-home-offer{margin:36px 0 48px;max-width:640px;scroll-margin-top:100px}
.researched-guide .guide-home-offer .compact-offer{margin:0}
.guide-home-offer .compact-offer .offer-art{max-width:210px;width:40%;right:10px;top:70px;height:200px}
.guide-home-offer .compact-offer .offer-terms{margin-top:44px}
.researched-guide #guide-application-offer{margin:44px 0 36px;scroll-margin-top:100px}
.guide-original-offer .has-christmas-arrival{position:relative;margin-top:0;padding-top:148px;isolation:isolate}
.guide-original-offer .has-christmas-arrival>.santa{top:24px;right:25%}
.guide-original-offer .guide-arrival-canvas{position:absolute;inset:0 auto auto 0;z-index:2;max-width:100%;pointer-events:none}
.guide-original-offer .offer-card__body{padding:clamp(24px,4vw,40px)}
.guide-original-offer .offer-card__terms{display:grid;gap:10px;line-height:1.6;font-size:13px}
.guide-original-offer .btn{white-space:normal;text-align:center;line-height:1.5}
.guide-original-offer a:not(.btn){color:#dce9f8;text-decoration:underline;text-underline-offset:3px}
.guide-original-offer .guide-original-links{font-size:14px;line-height:1.7;margin-top:20px}
.guide-original-offer .rewards h3{font-size:22px;line-height:1.15;font-weight:650;margin:0 0 14px;color:#fff}
.guide-original-offer .rewards h3 em{font-family:Georgia,serif;font-weight:400;color:#a8d5f5}
.guide-original-offer [data-referral-amount]{display:inline-block;min-width:3ch;text-align:right;font-variant-numeric:tabular-nums}
.guide-original-offer [data-referral-discount]{min-width:7ch;text-align:center}
.guide-original-offer .count-label{min-height:2.8em}
@media(max-width:420px){.guide-original-offer .rewards h3{font-size:17px}}
.guide-original-offer .offer-card__orbit,.guide-original-offer .offer-card__sheen::before,.guide-original-offer .auth-card-snow i{animation-iteration-count:1!important}
.guide-home-offer.has-festive-offer .compact-offer .present{animation:parcel-santa-throw 8.5s linear both}
.guide-home-offer.has-festive-offer .compact-offer .gift-lid{animation:delivery-lid 8.5s linear both}
.guide-home-offer.has-festive-offer .compact-offer .price-ticket{animation:delivery-price 8.5s linear both}
.guide-home-offer .compact-offer .star,.guide-home-offer .compact-offer .gift-glow,.guide-home-offer .compact-offer .orbit-two,.guide-home-offer .festive-snow i{animation-iteration-count:1!important}
.guide-home-offer:not(.gift-motion-ready) .offer-art *{animation:none!important}
.guide-home-offer:not(.gift-motion-ready) .delivery-van{display:none}
.guide-home-offer:not(.gift-motion-ready) .present{opacity:1!important;transform:none!important}
.guide-home-offer:not(.gift-motion-ready) .gift-lid{transform:translateY(-150px) rotate(-10deg)!important}
.guide-home-offer:not(.gift-motion-ready) .price-ticket{opacity:1!important;scale:1!important}
.guide-home-offer .offer-terms{font-size:13px;line-height:1.65}
@media(prefers-reduced-motion:reduce){.guide-home-offer *,.guide-home-offer *::before,.guide-home-offer *::after,.guide-original-offer *,.guide-original-offer *::before,.guide-original-offer *::after{animation:none!important;transition:none!important}.guide-home-offer .present{opacity:1!important;transform:none!important}.guide-home-offer .gift-lid{transform:translateY(-150px) rotate(-10deg)!important}.guide-home-offer .price-ticket{opacity:1!important;scale:1!important}.guide-home-offer .delivery-van{display:none!important}}
